(async()=>{const root=document.getElementById('orionModuleRoot');const fetchText=async p=>{const r=await fetch(p,{cache:'no-store'});if(!r.ok)throw new Error(p+' HTTP '+r.status);return r.text();};try{const css=(await Promise.all(["./style/style-001.part","./style/style-002.part"].map(fetchText))).join('');const style=document.createElement('style');style.textContent=css;document.head.appendChild(style);const html=(await Promise.all(["./body/body-001.part","./body/body-002.part","./body/body-003.part"].map(fetchText))).join('');root.outerHTML=html;const js=(await Promise.all(["./script/script-001.part","./script/script-002.part","./script/script-003.part","./script/script-004.part","./script/script-005.part"].map(fetchText))).join('');const script=document.createElement('script');script.textContent=js;document.body.appendChild(script);document.dispatchEvent(new Event('DOMContentLoaded',{bubbles:true}));}catch(error){console.error(error);root.textContent='No se pudo cargar el módulo ORION Ortodoncia.';root.setAttribute('role','alert');}})();